-- Schema for VpnServerClientTraffics hypertable PoC (TimescaleDB Community PG17).
CREATE EXTENSION IF NOT EXISTS timescaledb;

CREATE SCHEMA IF NOT EXISTS xgb_dashopnvpn;

DROP TABLE IF EXISTS xgb_dashopnvpn."VpnServerClientTraffics" CASCADE;

CREATE TABLE xgb_dashopnvpn."VpnServerClientTraffics" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "VpnServerId" integer NOT NULL,
    "ExternalId" character varying(255) NOT NULL,
    "SessionId" uuid NOT NULL,
    "BytesReceived" bigint NOT NULL,
    "BytesSent" bigint NOT NULL,
    "MeasuredAt" timestamptz NOT NULL,
    "CreateDate" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "LastUpdate" timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "UserId" integer NULL,
    -- Timescale requires unique/PK to include the partition column.
    PRIMARY KEY ("MeasuredAt", "Id")
);

SELECT create_hypertable(
    'xgb_dashopnvpn."VpnServerClientTraffics"',
    'MeasuredAt',
    chunk_time_interval => INTERVAL '7 days',
    create_default_indexes => false
);

CREATE UNIQUE INDEX "UX_ClientTraffic_Server_Session_At"
    ON xgb_dashopnvpn."VpnServerClientTraffics" ("VpnServerId", "MeasuredAt", "SessionId");

CREATE INDEX "IX_ClientTraffic_External_At"
    ON xgb_dashopnvpn."VpnServerClientTraffics" ("ExternalId", "MeasuredAt");

SELECT extname, extversion FROM pg_extension WHERE extname = 'timescaledb';
SHOW timescaledb.license;
